def build_agent(sandbox):
    # Initialize agent state if not already done
    if not hasattr(sandbox, 'agent_state'):
        sandbox.agent_state = {
            'current_phase': 'to_gate1',
            'passed_gate1': False,
            'passed_gate2': False,
            'previous_pos': sandbox.get_craft_position()
        }
    return None

def agent_action(sandbox, agent_body, step_count):
    # Extract state
    state = sandbox.agent_state
    current_phase = state['current_phase']
    passed_gate1 = state['passed_gate1']
    passed_gate2 = state['passed_gate2']
    previous_pos = state['previous_pos']

    # Get current position and state
    current_pos = sandbox.get_craft_position()
    current_heat = sandbox.get_heat()
    overheat_limit = sandbox.get_overheat_limit()
    remaining_steps = 10000 - step_count

    # Check for overheating
    if current_heat >= overheat_limit:
        return

    # Determine target
    if current_phase == 'to_gate1':
        target = (13.0, 2.0)
        # Check if passed Gate 1
        if not passed_gate1:
            if is_in_gate1(current_pos):
                if not is_in_gate1(previous_pos):
                    state['passed_gate1'] = True
                    state['current_phase'] = 'to_gate2'
        else:
            state['current_phase'] = 'to_gate2'
    elif current_phase == 'to_gate2':
        target = (23.0, 2.4)
        # Check if passed Gate 2
        if not passed_gate2:
            if is_in_gate2(current_pos):
                if not is_in_gate2(previous_pos):
                    state['passed_gate2'] = True
                    state['current_phase'] = 'to_target'
        else:
            state['current_phase'] = 'to_target'
    elif current_phase == 'to_target':
        target = (30.0, 3.5)
        # Check if reached target
        if is_in_target(current_pos):
            return

    # Update previous position
    state['previous_pos'] = current_pos

    # Calculate direction vector
    dx = target[0] - current_pos[0]
    dy = target[1] - current_pos[1]
    magnitude = (dx**2 + dy**2)**0.5
    if magnitude > 0:
        direction = (dx/magnitude, dy/magnitude)
    else:
        direction = (0, 0)

    # Calculate max allowable thrust based on remaining heat
    if remaining_steps <= 0:
        return

    remaining_heat_capacity = overheat_limit - current_heat
    if remaining_heat_capacity <= 0:
        return

    # Assume thrust magnitude is proportional to remaining heat capacity
    max_thrust = remaining_heat_capacity / remaining_steps
    thrust_magnitude = min(1.0, max_thrust)  # Cap thrust to prevent overshooting

    # Apply thrust in direction of target
    f1 = thrust_magnitude * direction[0]
    f2 = thrust_magnitude * direction[1]

    sandbox.apply_thrust(f1, f2)

def is_in_gate1(pos):
    x, y = pos
    return 12.0 <= x <= 14.0 and 1.0 <= y <= 2.8

def is_in_gate2(pos):
    x, y = pos
    return 22.0 <= x <= 24.0 and 1.8 <= y <= 3.0

def is_in_target(pos):
    x, y = pos
    return 28.0 <= x <= 32.0 and 2.0 <= y <= 5.0
